head.script:
		var PAGE_CNT = WebSquare.net.getParameter( "PAGE_CNT" );
     	var PAGE_ROWS = 15;
     	var list_cnt = "";
     	var BISComBoardDTO = "";
     	var prevSelectColNm = WebSquare.net.getParameter( "prevSelectColNm" );
   	var prevSearchText = WebSquare.net.getParameter( "prevSearchText" );
     	var TRANS_MODE = 0;
     	var WRITE_TYPE = 1; //글쓰기(1), 댓글쓰기(2)
     	var registUser = parent.gsUserId;
     	var registCompCd = parent.gsCompanyCd;
     	var pBoardInfo = WebSquare.net.getParameter( "boardInfo" );  // 게시판정보
     	var pStatementId = WebSquare.net.getParameter( "statementId" );	//글번호
		var pHiddenCol = WebSquare.net.getBASE64Parameter("hiddenCol");


		var pBoardTyp = "";
		var totalCount = "";

      /**************************************************************************
		* function    : cbmDataInit
		* Description : 게시판 콤보 리스트 설정
		* Parameter   : null
		* Return      : null
		**************************************************************************/	
		function cbmDataInit() {
			this.document.title=divisionNm;
			resizeIframe();

			if(PAGE_CNT == ""){
				PAGE_CNT = 1;
			}

			setTimeout(function(){

				//mobileChk();


				WebSquare.ModelUtil.removeChildNodes( "BISComBoardInfoDTO" );
	        	var BISComBoardInfoDTO =  {"BISComBoardInfoDTO":{}};

	        	pfm_insertValue(BISComBoardInfoDTO,"boardID", pBoardInfo);

	        	var BISComDspDatDTO =  {"BISComDspDatDTO":{}};
	        	callProFrameSync("BIS-COM","BISComBoardInfoSO","selectBoardInfo",BISComBoardInfoDTO, "BISComBoardInfoDTO","respInfo");
        	}, 100);
		}


		/**************************************************************************
		* function    : cbmDataInit
		* Description : 게시판 콤보 리스트 설정
		* Parameter   : null
		* Return      : null
		**************************************************************************/	
		function mobileChk() {
				if (isMobile()) {
            	pageList1.hide();
               pageControl1.show();
            } else {
               pageList1.show();
               pageControl1.hide();
            }
		}


		/**************************************************************************
		 * function    : searchData
		 * Description : 게시판 조회
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/	
		function searchData(pageNo) {

			if(pageNo != 1) PAGE_CNT = pageNo;
			//mobileChk();

			WebSquare.ModelUtil.removeChildNodes( "BISComBoardDTO" );

        	BISComBoardDTO =  {"BISComBoardDTO":{}};
        	/*
        	pfm_insertValue(BISComBoardDTO,"boardID", pBoardInfo);
        	pfm_insertValue(BISComBoardDTO,"boardTyp", pBoardTyp);
        	pfm_insertValue(BISComBoardDTO,"pageCnt", PAGE_CNT);
        	pfm_insertValue(BISComBoardDTO,"pageRows", PAGE_ROWS);

        	if (searchText.getValue() != "") {
        		if (selectColNm.getValue() == "0") pfm_insertValue(BISComBoardDTO, "title", searchText.getValue());
        		if (selectColNm.getValue() == "1") pfm_insertValue(BISComBoardDTO, "registDt", searchText.getValue());
        		if (selectColNm.getValue() == "2") pfm_insertValue(BISComBoardDTO, "content", searchText.getValue());
        		//if (selectColNm.getValue() == "3") pfm_insertValue(BISComBoardDTO, "registOrg", searchText.getValue());

        		prevSelectColNm = selectColNm.getValue();
        		prevSearchText = searchText.getValue();
        	}
        	*/
	      setValue("BISComBoardDTO/boardID", pBoardInfo);
        	setValue("BISComBoardDTO/boardTyp", pBoardTyp);
        	setValue("BISComBoardDTO/pageCnt", PAGE_CNT);
        	setValue("BISComBoardDTO/pageRows", PAGE_ROWS);

        	if (searchText.getValue() != "") {
        		if (selectColNm.getValue() == "0") setValue("BISComBoardDTO/title", textEncoding(searchText.getValue()));
        		if (selectColNm.getValue() == "1") setValue("BISComBoardDTO/registDt", textEncoding(searchText.getValue()));
        		if (selectColNm.getValue() == "2") setValue("BISComBoardDTO/content", textEncoding(searchText.getValue()));
        	}

        	callProFrameSync("BIS-COM","BISComBoardSO","selectBoard",BISComBoardDTO, "BISComBoardDTO","resp");
		}


     	/**************************************************************************
      * function    : callBack
      * Description : submission 실행 후 Callback
      * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
      * Return      : null
      **************************************************************************/
     	function callBack(svcId,fnId,strResp) {   
     		if (svcId == "BISComBoardInfoSO") {
				if (fnId == "selectBoardInfo") {
					pBoardTyp = getValue("respInfo/root/message/BISComBoardInfoListDTO/BISComBoardInfoDTO/boardTyp");
					searchData(PAGE_CNT);
					resizeIframe();
      		}
      	}else if (svcId == "BISComBoardSO") {
     			if (fnId == "selectBoard") {
     				grdMain.setXML( getInstanceNode("resp/root/message/BISComBoardListDTO") );

     				if(pBoardInfo == "7"){
	     				for(var i=0; i<grdMain.getRowCount(); i++){
	     					grdMain.setCellData( i , 2 , "금융투자협회" );
	     				}
     				}

     				totalCount = WebSquare.ModelUtil.getInstanceValue( "resp/root/message/BISComBoardListDTO[1]/BISComBoardDTO/total");

     				for(var i=1; i<=totalCount; i++){
     					setValue("resp/root/message/BISComBoardListDTO/BISComBoardDTO["+i+"]/title", textEncoding((getValue("resp/root/message/BISComBoardListDTO/BISComBoardDTO["+i+"]/title"))));
     					setValue("resp/root/message/BISComBoardListDTO/BISComBoardDTO["+i+"]/content", textEncoding((getValue("resp/root/message/BISComBoardListDTO/BISComBoardDTO["+i+"]/content"))));
     				}

     				var pageCnt = totalCount/PAGE_ROWS;

     				if(Math.ceil(pageCnt) > pageCnt){
     					pageCnt = Math.ceil(pageCnt); 
     				}

     				if (PAGE_CNT == 1) {
     					pageList1.setCount( pageCnt, false );     				
     				}else{
     					pageList1.setCount( pageCnt, true );
     					pageList1.setSelectedIndex( PAGE_CNT );

     				}
     				resizeIframe();	
     			}
     		} 
		}


		/**************************************************************************
		 * function    : imgColumn
		 * Description : grid cell에 이미지 보여주기
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function imgColumn(data,formattedData,row,col){
			if (data.length == 0) return "";
			var str = "";
			for(var i=0;i<data.split("^").length;i++){
				if (data.split("^")[i].split("|")[4].length > 0) {
					str = str + '<img src="/images/btn/file_btn00.gif" style="cursor:pointer; padding-left:5px"' + ' title=' + data.split("^")[i].split("|")[4] + ' onclick="fileDownload('+i+','+row+')"/>';
				}
			}
			return str;
		}

		/**************************************************************************
		 * function    : fileDownload
		 * Description : 파일 다운로드
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function fileDownload(index, row) {
			var str = grdMain.getCellData(row, "attachFile");
			var arr = getFileName(index, str);
			comFileDownload(arr[1], arr[2], arr[3], arr[4]);
		}	

		/**************************************************************************
       * function    : getFileName
       * Description : 파일 정보에서 Array 리턴
       * Parameter   : index, str
       * Return      : null
       **************************************************************************/
      function getFileName(index, str) {
      	if (str == undefined || str == "") return;

			if (str.indexOf("^") > 0) {
			    var arr = str.split("^");
			    if (arr[index] != undefined && arr.length > 0 && arr.length >= index) {
					return arr[index].split("|");
			    }
			} else {
				if (index > 0) return;
				return str.split("|");
			}
      }		


       /**************************************************************************
		 * function    : titleColumn
		 * Description : 댓글형 grid title 컬럼 level 설정하여 보여주기
		 * Parameter   : data,formattedData,row,col
		 * Return      : null
		 **************************************************************************/
		 function titleColumn(data,formattedData,row,col){
			var str = null;

			if(grdMain.getCellData( row , "depth" ) != 1 && grdMain.getCellData( row , "depth" ) != ""){
				// 댓글은 depth에 따라 margin-left를 설정하여 공백을 준다.
				str = "<a style='margin-left:"+(Number(grdMain.getCellData( row , "depth" ))-2)*10 +"px' class='level2'>"+data+"</a>";
			}else{
				str = "<a class='level1'>"+data+"</a>";
			}

			return str;
		 }

       /**************************************************************************
        * function    : formatDate
        * Description : 날짜 포맷
        * Parameter   : str
        * Return      : null
        **************************************************************************/
       function formatDate(str) {
			if(str == null || str == undefined || str == "") return "";
			str = str.length > 8 ? str.substr(0,8) : str;
			if (str.indexOf("/") > 0) return str;
			return str.toDateString(USER_DATE_FORMAT_DELIM);
		 }


		/**************************************************************************
       * function    : showDetail
       * Description : 상세보기 화면 전환
       * Parameter   : null
       * Return      : null
       **************************************************************************/
       function showDetail(row){
       	 pStatementId = grdMain.getCellData(row, "statementId");
          parent.maincontent.setSrc("/xml/board/BISItgtBoardViewPDS.xml"
          									+ "&divisionId=" + divisionId + "&topMenuIndex=" + topMenuIndex 
          									+ "&boardInfo=" + pBoardInfo + "&boardTyp=" + pBoardTyp
          									+ "&statementId=" + pStatementId + "&PAGE_CNT=" + PAGE_CNT

          								  );


       }


       /**************************************************************************
       * function    : showWrite
       * Description : 글쓰기 화면 전환
       * Parameter   : null
       * Return      : null
       **************************************************************************/
       function showWrite(gb){
       	if(gb == "U") pStatementId = grdMain.getCellData(row, "statementId");
          parent.maincontent.setSrc("/xml/board/BISItgtBoardWrite.xml"
          									+ "&divisionId=" + divisionId + "&topMenuIndex=" + topMenuIndex 
          									+ "&boardInfo=" + pBoardInfo + "&boardTyp=" + pBoardTyp
          									+ "&statementId=" + pStatementId + "&PAGE_CNT=" + PAGE_CNT
          									+ "&saveGb=" + gb
          								  );


       }		 
		cbmDataInit();
